using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Xml;
namespace ClearDisk {
 internal sealed class BleachBitStructuredSource:IStructuredCleanupSource,IStructuredCleanupRevision {
  readonly string application,rulesPath;readonly Func<string,CompatibleJob> jobs;string adapted,loadedRevision;string[] ruleDiagnostics=new string[0];readonly object state=new object();long listGeneration;
  internal string[] RuleDiagnostics {get{lock(state)return (string[])ruleDiagnostics.Clone();}}
  public string Revision {get{return rulesPath==null?new RuleReleaseManager(application).SelectionRevision():RuleReleaseManager.ValidateKnown(rulesPath);}}
  internal BleachBitStructuredSource(string directory):this(directory,null){}
  internal BleachBitStructuredSource(string directory,string selectedRules):this(directory,selectedRules,path=>new CompatibleJob(path)){}
  internal BleachBitStructuredSource(string directory,string selectedRules,Func<string,CompatibleJob> factory){application=NativeFiles.Normalize(directory);rulesPath=selectedRules;jobs=factory;}
  internal static string AdaptRules(string raw,out string[] rejected){var diagnostics=new List<string>();var output=new StringBuilder();var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string part in Regex.Split(raw,@"(?m)(?=^\[)")){
   if(!part.StartsWith("[",StringComparison.Ordinal)){output.Append(part);continue;}CommunityEntry e;using(var reader=new StringReader(part)){var entries=CommunityRules.Parse(reader).Catalog;if(entries.Count!=1){diagnostics.Add("规则段格式无效，整段禁用。");continue;}e=entries[0];}
   string reason=null;if(e.UnresolvedConditions.Count>0)reason="未知指令 "+String.Join(",",e.UnresolvedConditions);
   if(e.Directives.Any(d=>d.Value.Count!=1))reason="重复指令";
   foreach(string value in e.FileKeys){string[] p=value.Split('|');if(p.Length<2||p.Length>4||p.Skip(2).Any(v=>v!="RECURSE"&&v!="REMOVESELF")||String.IsNullOrWhiteSpace(p[0]))reason="不支持的 FileKey 语法";}
   foreach(string value in e.ExcludeKeys){string[] p=value.Split('|');if(p.Length<2||p.Length>3||(p[0]!="FILE"&&p[0]!="PATH"))reason="不支持的 ExcludeKey 语法";}
   if(e.Directives.Where(d=>Regex.IsMatch(d.Key,@"^RegKey\d+$",RegexOptions.IgnoreCase)).Any(d=>d.Value[0].Split('|').Length>2))reason="不支持的 RegKey 语法";
   if(!e.Directives.ContainsKey("LangSecRef")&&!e.Directives.ContainsKey("Section"))reason="缺少分类";
   string category=e.Directives.ContainsKey("LangSecRef")?e.Directives["LangSecRef"][0]:e.Directives.ContainsKey("Section")?e.Directives["Section"][0]:"";string normalized=category+"."+Regex.Replace(Regex.Replace(e.Name.ToLowerInvariant(),@"[^a-z0-9]","_"),"_+","_").Trim('_');if(!used.Add(normalized))reason="归一化规则 ID 重复";
   if(reason==null)output.Append(part);else diagnostics.Add(e.Name+"：整段禁用："+reason);
  }rejected=diagnostics.ToArray();return output.ToString();}
  string Rules(string runtime){string path=rulesPath??new RuleReleaseManager(application).GetActiveRules();
   path=NativeFiles.Normalize(path);using(var pins=new NativeFiles.ParentLocks(path))using(var handle=NativeFiles.OpenData(path,false)){var info=NativeFiles.Info(handle);if(info.Links!=1||(info.Attributes&0x410)!=0||NativeFiles.Final(handle)!=path)throw new IOException("规则来源路径或链接异常。");string hash=BitConverter.ToString(Convert.FromBase64String(NativeFiles.Hash(handle,CancellationToken.None))).Replace("-","");if(hash!="359543D47AC69C5300686ED55A36736C82BE17E6EE53F10CE82F2AD52FB558F8"&&hash!="54CE86839B5C5E6ED796CC17B0CE879A795920BA5FCB930DC84BBA7ECE535C5B")throw new IOException("规则源不是已认证的内置发行版本。");using(var bytes=new MemoryStream()){StructuredFileIo.Copy(handle,bytes);return new UTF8Encoding(false,true).GetString(bytes.ToArray()).TrimStart('\uFEFF');}}
  }
  public CompatibleOption[] List(CancellationToken token){long generation;lock(state){generation=++listGeneration;adapted=null;loadedRevision=null;ruleDiagnostics=new string[0];}string revision=Revision;using(var runtime=new BleachBitRuntimeLease(application)){string[] rejected;string rules=AdaptRules(Rules(runtime.Root),out rejected);var metadata=Metadata(runtime.Root,rules);string output=Run(runtime.Root,new[]{"--list-cleaners"},new StructuredScanControl(),token,null,null,rules);var values=new List<CompatibleOption>();foreach(string line in output.Split('\n')){string id=line.Trim();if(id.Length==0)continue;if(!Regex.IsMatch(id,@"\A[a-zA-Z0-9_]+\.[a-zA-Z0-9_]+\z"))throw new IOException("结构化目录输出含未知内容。");CompatibleOption option;if(!metadata.TryGetValue(id,out option))option=new CompatibleOption(id,id,"按冻结文件快照执行；特殊操作单独列出。","请核对精确路径和风险；不支持的特殊动作不会执行。");if(CompatibleCleanupEngine.AllowedId(id))values.Add(option);}token.ThrowIfCancellationRequested();if(values.Count==0||revision!=Revision)throw new IOException("清理目录为空或规则选择已变化；请重新读取目录。");lock(state){if(generation!=listGeneration)throw new InvalidOperationException("此引擎目录读取已被较新的操作取代。");adapted=rules;loadedRevision=revision;ruleDiagnostics=rejected;}return values.ToArray();}}
  static string Normal(string value){return Regex.Replace(Regex.Replace(value.ToLowerInvariant(),@"[^a-z0-9]","_"),"_+","_").Trim('_');}
  static Dictionary<string,CompatibleOption> Metadata(string runtime,string ruleText){var result=new Dictionary<string,CompatibleOption>(StringComparer.Ordinal);var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null};foreach(string file in Directory.GetFiles(Path.Combine(runtime,"share","cleaners"),"*.xml")){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(file,settings))doc.Load(reader);XmlElement cleaner=doc.DocumentElement;if(cleaner==null||cleaner.Name!="cleaner")continue;foreach(XmlElement option in cleaner.SelectNodes("option")){string id=cleaner.GetAttribute("id")+"."+option.GetAttribute("id");result[id]=new CompatibleOption(id,Text(cleaner,"label")+" / "+Text(option,"label"),Text(option,"description"),Text(option,"warning"));}}
   var groups=new Dictionary<string,string>{{"3001","internet_explorer"},{"3005","edge_classic"},{"3006","edge_chromium"},{"3021","applications"},{"3022","internet"},{"3023","multimedia"},{"3024","utilities"},{"3025","windows"},{"3026","mozilla"},{"3027","opera"},{"3028","safari"},{"3029","google_chrome"},{"3030","thunderbird"},{"3031","windows_store"},{"3033","vivaldi"},{"3034","brave"}};using(var reader=new StringReader(ruleText))foreach(var entry in CommunityRules.Parse(reader).Catalog){List<string> values;string category=entry.Directives.TryGetValue("LangSecRef",out values)?values[0]:entry.Directives.TryGetValue("Section",out values)?values[0]:"unknown",group;string id="winapp2_"+(groups.TryGetValue(category,out group)?group:Normal(category))+"."+Normal(entry.Name);result[id]=new CompatibleOption(id,entry.Name.TrimEnd(' ','*'),"社区规则；普通文件按精确快照执行，设置动作单独列出。",entry.Warning);}
   result["system.tmp"]=new CompatibleOption("system.tmp","Windows / 临时文件","当前用户临时目录及 Windows Temp。","请先关闭安装程序和相关应用；未保存的临时内容可能丢失。");result["system.updates"]=new CompatibleOption("system.updates","Windows / 更新与旧安装","文件按冻结清单处理；停止服务等特殊动作不会混同为文件删除。","Windows.old 中的旧账户资料与系统回退可能永久丢失；不支持的维护动作单独报告。");return result;
  }
  static string Text(XmlElement node,string tag){var child=node.SelectSingleNode(tag);return child==null?"":child.InnerText;}
  public void Read(string[] ids,StructuredScanControl control,CancellationToken token,Action<StructuredCandidate> candidate,Action<string> diagnostic){string rules,revision;string[] rejected;lock(state){rules=adapted;revision=loadedRevision;rejected=ruleDiagnostics;}if(rules==null||revision!=Revision)throw new InvalidOperationException("请先重新读取当前规则版本目录。");foreach(string d in rejected)diagnostic(d);using(var runtime=new BleachBitRuntimeLease(application)){Run(runtime.Root,new[]{"--preview"}.Concat(ids).ToArray(),control,token,candidate,diagnostic,rules);}}
  string Run(string runtime,string[] args,StructuredScanControl control,CancellationToken token,Action<StructuredCandidate> candidate,Action<string> diagnostic,string ruleText){using(var job=jobs(application)){
   string ruleFile=Path.Combine(job.Root,"structured-winapp2.ini"),sidecar=Path.Combine(job.Root,"structured.jsonl"),pause=Path.Combine(job.Root,"structured.pause");File.WriteAllText(ruleFile,ruleText,new UTF8Encoding(false));File.WriteAllText(sidecar,"",new UTF8Encoding(false));
   if(args.Any(v=>!Regex.IsMatch(v,@"\A[-a-zA-Z0-9_.]+\z")))throw new IOException("不接受任意引擎参数。");
   var psi=new ProcessStartInfo(Path.Combine(runtime,"bleachbit_console.exe"),String.Join(" ",args)){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=runtime,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};foreach(string key in new[]{"PYTHONPATH","PYTHONHOME","PYTHONSTARTUP","PYTHONINSPECT"})psi.EnvironmentVariables.Remove(key);
   psi.EnvironmentVariables["BLEACHBIT_TEST_OPTIONS_DIR"]=job.Root;psi.EnvironmentVariables["PYTHONDONTWRITEBYTECODE"]="1";psi.EnvironmentVariables["CDRIVE_STRUCTURED_RULES"]=ruleFile;
   if(candidate!=null){psi.EnvironmentVariables["CDRIVE_STRUCTURED_OUTPUT"]=sidecar;psi.EnvironmentVariables["CDRIVE_STRUCTURED_PAUSE"]=pause;}else{psi.EnvironmentVariables.Remove("CDRIVE_STRUCTURED_OUTPUT");psi.EnvironmentVariables.Remove("CDRIVE_STRUCTURED_PAUSE");}
   using(var process=new Process{StartInfo=psi})using(var processJob=new NativeProcessJob())using(var input=new FileStream(sidecar,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))using(var reader=new StreamReader(input,new UTF8Encoding(false,true))){
    token.ThrowIfCancellationRequested();if(!process.Start())throw new IOException("无法启动结构化预览。");processJob.Assign(process.Handle);var stdout=Task.Factory.StartNew(()=>BleachBitBackend.Drain(process.StandardOutput,null),TaskCreationOptions.LongRunning);var stderr=Task.Factory.StartNew(()=>BleachBitBackend.Drain(process.StandardError,null),TaskCreationOptions.LongRunning);string carry="";bool complete=false;int errors=0;var json=new JavaScriptSerializer{MaxJsonLength=1048576};
    Action pump=()=>{string chunk=carry+reader.ReadToEnd();int end=chunk.LastIndexOf('\n');if(end<0){carry=chunk;if(carry.Length>1048576)throw new IOException("结构化记录过大。");return;}carry=chunk.Substring(end+1);using(var lines=new StringReader(chunk.Substring(0,end))){string line;while((line=lines.ReadLine())!=null){if(line.Length==0)continue;if(complete)throw new IOException("结构化完成标记后存在额外输出。");var row=json.Deserialize<Dictionary<string,object>>(line);string record=Get(row,"record");if(record=="complete"){complete=true;errors=Convert.ToInt32(row["errors"],CultureInfo.InvariantCulture);}else if(record=="error"){if(diagnostic!=null)diagnostic(Get(row,"rule")+": 引擎预览错误："+Get(row,"detail"));}else if(record=="candidate"){if(candidate==null)throw new IOException("目录过程出现清理明细。");candidate(new StructuredCandidate{RuleId=Get(row,"rule"),Kind=Get(row,"command"),Path=Get(row,"path"),Detail=Get(row,"detail"),RegistryKey=Get(row,"key"),RegistryValue=Get(row,"value")});}else throw new IOException("未知结构化记录。");}}if(carry.Length>1048576)throw new IOException("结构化记录过大。");};
    try{while(!process.WaitForExit(50)){token.ThrowIfCancellationRequested();if(control.IsPaused){if(!File.Exists(pause))File.WriteAllText(pause,"paused");}else if(File.Exists(pause))File.Delete(pause);pump();}pump();Task.WaitAll(stdout,stderr);token.ThrowIfCancellationRequested();if(process.ExitCode!=0)throw new IOException("预览进程失败："+stderr.Result);if(candidate!=null&&(!complete||carry.Length!=0))throw new IOException("结构化明细不完整，不授予执行资格。");if(errors>0&&diagnostic!=null)diagnostic("预览报告 "+errors+" 个错误；仅已完整冻结的普通文件获得候选资格。");if(!String.IsNullOrWhiteSpace(stderr.Result)&&diagnostic!=null)diagnostic("引擎诊断："+stderr.Result);return stdout.Result;}
    catch{processJob.Stop();process.WaitForExit();Task.WaitAll(stdout,stderr);throw;}
   }
  }}
  static string Get(Dictionary<string,object> row,string key){object value;return row.TryGetValue(key,out value)&&value!=null?Convert.ToString(value,CultureInfo.InvariantCulture):null;}
 }
